import re
import math
from collections import Counter

from config import STOPWORDS, EXPANSIONS, BROAD_TERMS


def tokens(text):
    return re.findall(r"[a-z]+|[\u4e00-\u9fff]{2,}", text.lower())


def _normalize_terms(text):
    terms = set(tokens(text))
    terms -= STOPWORDS
    expanded = set(terms)
    for key, values in EXPANSIONS.items():
        if key in terms:
            for value in values:
                expanded.update(tokens(value))
    return expanded


def _split_clauses(query):
    parts = re.split(
        r"[?？,，;；。.!！\n]|\band\b|\bor\b|与|和|以及|并且|或者",
        query.lower(),
    )
    return [p.strip() for p in parts if p.strip()]


def search_context(chunks, query, top_k=3, neighbor_window=1, max_context=8):
    if not chunks:
        return []

    clauses = [_normalize_terms(c) for c in _split_clauses(query)]
    clauses = [c for c in clauses if c]

    all_terms = set()
    for clause in clauses:
        all_terms |= clause

    weights = {t: 1.0 for t in all_terms}
    for specific, broads in BROAD_TERMS.items():
        if specific in all_terms:
            for broad in broads:
                if broad in weights:
                    weights[broad] = 0.1

    n = len(chunks)
    df = Counter()
    for chunk in chunks:
        for term in set(tokens(chunk["text"])):
            df[term] += 1
    idf = {t: math.log((n + 1) / (df[t] + 1)) + 1.0 for t in df}

    def score(chunk):
        chunk_terms = set(tokens(chunk["text"]))
        matched = all_terms & chunk_terms
        if not matched:
            return 0.0
        coverage = len(matched) / len(all_terms)
        rarity = sum(weights[t] * idf.get(t, 0.0) for t in matched)
        return coverage * rarity

    ranked = sorted(chunks, key=score, reverse=True)

    selected = []
    selected_ids = set()

    for clause in clauses:
        best = None
        best_score = -1.0
        for chunk in ranked:
            if chunk["id"] in selected_ids:
                continue
            if clause & set(tokens(chunk["text"])):
                s = score(chunk)
                if s > best_score:
                    best = chunk
                    best_score = s
        if best is not None:
            selected.append(best)
            selected_ids.add(best["id"])

    for chunk in ranked:
        if len(selected) >= top_k:
            break
        if chunk["id"] in selected_ids:
            continue
        if score(chunk) > 0:
            selected.append(chunk)
            selected_ids.add(chunk["id"])

    result = [{**c, "retrieval_reason": "semantic"} for c in selected]

    neighbor_ids = set()
    for chunk in selected:
        if len(result) >= max_context:
            break
        source = chunk.get("source")
        page = chunk.get("page")
        if source is None or page is None:
            continue
        for delta in range(-neighbor_window, neighbor_window + 1):
            if delta == 0:
                continue
            target_page = page + delta
            for other in chunks:
                if other.get("source") == source and other.get("page") == target_page:
                    if other["id"] not in selected_ids and other["id"] not in neighbor_ids:
                        result.append({**other, "retrieval_reason": "neighbor"})
                        neighbor_ids.add(other["id"])
                        if len(result) >= max_context:
                            break
            if len(result) >= max_context:
                break

    return result

